                    y0+wood_drawer_runner_reg_pos(drawer_box_depth,n),
                    z0+wood_drawer_runner_height/2,
                    wood_drawer_runner_thickness+2,
                    wood_slide_registration_hole_diameter
                );
            }
        }
    }
}

module wood_fixed_rail_cut() {
    difference() {
