            );

        paint("face_frame")
            face_frame_rail_3d(
                face_frame_bottom_z,
                effective_face_frame_bottom_rail_width,
                "bottom"
            );

        if (face_frame_mid_rail_active)
            paint("face_frame")
                face_frame_mid_rail_3d();

        if (face_frame_center_stile_enabled)
            paint("face_frame")
                face_frame_center_stile_3d();
    }
}


