cabinet_layout_mode = "legacy"; // [legacy, mixed_bays, sections]

mixed_bay_count = 1; // [1:1:4]

mixed_bay_types = ["drawers","drawers","drawers","drawers"];

// Relative clear opening widths, one entry per bay.
