target_module_count_x = 10; // [1:1:40]

target_module_edge_clearance_x = 1; // [0:0.25:20]

target_module_pitch_y = 42; // [10:0.5:100]

target_module_count_y = 8; // [1:1:40]

target_module_edge_clearance_y = 1; // [0:0.25:20]

