fronts_cover_bottom_lip = true;

// Gap between adjacent decorative doors.
door_gap = 3;

// Gap between adjacent decorative drawer faces.
drawer_gap = 3;

/* [Doors / Layout] */

// Relative widths for side-by-side door bays. Only the first door_count
