module drawer_divider_perimeter_operation_geometry_2d() {
    if (has_drawers && include_drawer_divider_grid
        && drawer_divider_perimeter_capture_active()) {
        g = layout_gap;
        d = drawer_box_depth;
        for (b=[0:active_drawer_bank_count()-1])
