        if (effective_hinge_style == "euro_35mm") {
            dw = door_each_width(i);

            for (j=[0:hinge_count-1])
                translate([
                    hinge_local_x(dw,i),
                    hinge_local_z(j),
                    door_thickness
                        - min(
                            effective_hinge_cup_depth,
                            door_thickness-0.5
