                bottom_y = side_y+bh+2*g;

                paint("drawer_bottom",pi)
                    translate([0,bottom_y,0])
                        drawer_bottom_print_part(b,i);

                if (drawer_divider_active_for(b,i)) {
                    for (n=[0:max(0,drawer_divider_x_count()-1)])
