    if (has_doors && door_face_height > 20) {
        if (mixed_bay_mode) {
            for (b=[0:active_mixed_bay_count-1])
                if (mixed_bay_is_type(b,"door"))
                    for (leaf=[0:mixed_bay_door_count(b)-1])
